pcall(ScenEdit_SetSidePosture, CFG_SCENARIO.side_blue, CFG_SCENARIO.side_red,  "H")
ok("红方/蓝方 关系: Hostile")

local function addUnitFromManifest(uid)
    local u = UNITS[uid]
    if not u then warn("manifest 缺单位: " .. uid); return end
    local props = {
        side = u.side, type = u.type, name = u.name,
        dbid = u.dbid, lat = u.lat, lon = u.lon,
    }
    if u.type == "Aircraft" then
        props.Altitude = u.altitude       -- CMO API 用 Altitude (大写 A)
        props.LoadoutID = u.loadout_id   -- 必须有 LoadoutID (MCP 查 DataAircraftLoadouts)
        props.proficiency = "Regular"
    elseif u.type == "Ship" then
        props.proficiency = "Veteran"
    elseif u.type == "Submarine" then
        props.proficiency = "Regular"
    end
    if u.side == CFG_SCENARIO.side_blue and CFG_SCENARIO.blue_autodetectable then
        props.autodetectable = true
    end
    -- 检查关键字段
    if type(props.Altitude) ~= "number" and type(props.altitude) ~= "number" then
        props.Altitude = tonumber(u.altitude) or 5000  -- fallback
    end
    _errnum_ = 0
    _errmsg_ = ""
    pcall(ScenEdit_AddUnit, props)
    if (_errnum_ or 0) ~= 0 then
        warn("AddUnit 失败 " .. uid .. " | err=" .. tostring(_errmsg_) ..
             " | lat=" .. tostring(u.lat) .. " (type=" .. type(u.lat) ..
             ") | lon=" .. tostring(u.lon) .. " (type=" .. type(u.lon) .. ")")
        -- 尝试自动转换 lat/lon 为数字
        props.lat = tonumber(u.lat) or 0
        props.lon = tonumber(u.lon) or 0
        _errnum_ = 0
        _errmsg_ = ""
        pcall(ScenEdit_AddUnit, props)
        if (_errnum_ or 0) ~= 0 then
            warn("AddUnit 重试仍失败 " .. uid .. " | err=" .. tostring(_errmsg_))
            return
        end
        ok(("AddUnit %s (lat/lon 转数字重试成功)"):format(uid))
    end
    -- 立即验证
    local verify = ScenEdit_GetUnit({ side = u.side, name = u.name })
    if verify and verify.guid then
        ok(string.format("%-15s | %s | %-10s | dbid=%-5d @ (%s, %s) GUID=%s",
            uid, u.side, u.type, u.dbid, u.lat, u.lon, verify.guid))
    else
        warn(("添加后查不到 %s"):format(uid))
    end
end

