local function clearUnitWeapons(side, name)
    local u = ScenEdit_GetUnit({ side = side, name = name })
    if not u or not u.guid then warn("找不到 " .. side .. "/" .. name); return false end
    local jobs = {}
    for _, m in ipairs(u.mounts or {}) do
        for _, w in ipairs(m.mount_weapons or {}) do
            local cur = tonumber(w.wpn_current) or 0
            if cur > 0 then jobs[#jobs + 1] = { dbid = w.wpn_dbid, num = cur, mountid = m.mount_guid } end
        end
    end
    local done, fail = 0, 0
    for _, j in ipairs(jobs) do
        _errnum_ = 0
        ScenEdit_AddReloadsToUnit({ guid = u.guid, wpn_dbid = j.dbid, mount_guid = j.mountid, number = j.num, remove = true })
        if (_errnum_ or 0) == 0 then done = done + 1 else fail = fail + 1 end
    end
    ok(("%s: 减载归零 %d 条 (失败 %d)"):format(name, done, fail))
    return fail == 0
end

for _, uid in ipairs(CLEAR_LIST) do
    local u = UNITS[uid]
    if u then clearUnitWeapons(u.side, u.name) end
end

