local function reloadUnit(unitname, wpn_dbid, number)
    local side
    for _, u in pairs(UNITS) do if u.name == unitname then side = u.side; break end end
    if not side then warn("manifest 没找到单位: " .. unitname); return false end
    local u = ScenEdit_GetUnit({ side = side, name = unitname })
    if not (u and u.guid) then warn("找不到 " .. side .. "/" .. unitname); return false end
    _errnum_ = 0
    local ok2 = pcall(ScenEdit_AddReloadsToUnit, { side = side, unitname = unitname, wpn_dbid = wpn_dbid, number = number })
    if ok2 and (_errnum_ or 0) == 0 then
        ok(string.format("+ %d x [dbid=%d] -> %s", number, wpn_dbid, unitname))
        return true
    else
        warn(string.format("装弹失败 %s", unitname))
        return false
    end
end

for _, a in ipairs(AMMO) do reloadUnit(a.unitname, a.wpn_dbid, a.number) end

