print("")
print("[CMO] ============ STEP 4/4: 真延时打击 (TOT 事件驱动) ============")

-- 全局变量 (fireAt 沙箱需要)
_SIDE_RED             = CFG_SCENARIO.side_red
_SIDE_BLUE            = CFG_SCENARIO.side_blue
_BLUE_AUTODETECTABLE  = CFG_SCENARIO.blue_autodetectable
_CONTACT_SETTLE_DELAY = tonumber(CFG_SCENARIO.contact_settle_delay) or 15
_ALLOW_BOL_FALLBACK   = false
_CONTACT_CACHE        = {}

local function sameGuid(a, b) return a and b and tostring(a):lower() == tostring(b):lower() end

local function collectContacts(sideName)
    local out, seen = {}, {}
    local ok2, r = pcall(ScenEdit_GetContacts, { side = sideName })
    if ok2 and type(r) == "table" then
        for _, c in ipairs(r) do
            if c.guid or c.Guid then
                local key = tostring(c.guid or c.Guid)
                if not seen[key] then seen[key] = true; out[#out + 1] = c end
            end
        end
    end
    return out
end

local function findContactForTarget(tgt, tgtName)
    if not (tgt and tgt.guid) then return nil end
    local cacheKey = tostring(tgt.guid)
    if _CONTACT_CACHE[cacheKey] then return _CONTACT_CACHE[cacheKey] end
    pcall(ScenEdit_SetSideOptions, { side = _SIDE_RED, awareness = "OMNI" })
    local cs = collectContacts(_SIDE_RED)
    info(_SIDE_RED .. " contact count = " .. tostring(#cs))
    for _, c in ipairs(cs) do
        local cg = c.guid or c.Guid
        if cg and (sameGuid(c.actualunitid, tgt.guid) or sameGuid(c.actualUnitID, tgt.guid)
            or sameGuid(c.actualunitguid, tgt.guid) or sameGuid(c.actualUnitGuid, tgt.guid)
            or sameGuid(c.actual_guid, tgt.guid) or sameGuid(c.actualGuid, tgt.guid)) then
            _CONTACT_CACHE[cacheKey] = cg; return cg
        end
    end
    for _, c in ipairs(cs) do
        local cg = c.guid or c.Guid
        local nm = tostring(c.name or c.Name or c.actualunitname or "")
        if cg and tgtName and nm:find(tgtName, 1, true) then
            _CONTACT_CACHE[cacheKey] = cg; warn("按名字匹配: " .. tgtName); return cg
        end
    end
    return nil
end

-- fireAt (全局)
function fireAt(attackerName, targetName, wpnDbid, qty)
    local atk = ScenEdit_GetUnit({ side = _SIDE_RED, name = attackerName })
    local tgt = ScenEdit_GetUnit({ side = _SIDE_BLUE, name = targetName })
    if not (atk and atk.guid) then print("[CMO] [ERROR] 找不到攻击方 " .. attackerName); return false end
    if not (tgt and tgt.guid) then print("[CMO] [ERROR] 找不到目标 " .. targetName); return false end
    pcall(ScenEdit_SetUnit, { guid = tgt.guid, autodetectable = true })
    local contactGuid
    for attempt = 1, 3 do
        contactGuid = findContactForTarget(tgt, targetName)
        if contactGuid then break end
        if attempt < 3 then
            warn("Attempt " .. attempt .. "/3: 无 contact, 2s 重试...")
            local _t = ScenEdit_CurrentTime()
            while ScenEdit_CurrentTime() < _t + 2 do end
        end
    end
    if contactGuid then
        _errnum_ = 0
        ScenEdit_AttackContact(atk.guid, contactGuid, { mode = "1", weapon = wpnDbid, qty = qty })
        ok(attackerName .. " -> CONTACT 攻击 " .. targetName)
        return true
    else
        print("[CMO] [ERROR] " .. attackerName .. " 无 contact, 取消发射")
        return false
    end
end

-- TOT ticks
local function totTicks() local t = ScenEdit_CurrentTime(); return string.format("%.0f", (t + 62135596801) * 1e7) end

-- scheduleOne
local function scheduleOne(atkName, tgtName, wpn, delay, tag)
    delay = delay + _CONTACT_SETTLE_DELAY
    local evName = "Event " .. tag
    local trName = "Trig " .. tag
    local acName = "Act " .. tag
    local fireTime = totTicks()
    local script = ("fireAt(%q,%q,%d,1)\n"):format(atkName, tgtName, wpn)
    _errnum_ = 0
    pcall(ScenEdit_SetTrigger, { mode = "add", type = "Time", name = trName, Time = fireTime })
    pcall(ScenEdit_SetAction, { mode = "add", type = "LuaScript", name = acName, ScriptText = script })
    pcall(ScenEdit_SetEvent, evName, { mode = "add", IsActive = true, IsRepeatable = false })
    pcall(ScenEdit_SetEventTrigger, evName, { mode = "add", name = trName })
    pcall(ScenEdit_SetEventAction, evName, { mode = "add", name = acName })
    ok(("调度 %s -> %s | +%ds | %s"):format(atkName, tgtName, delay, tag))
    return true
end

-- 主调度
local total_sched = 0
for i, s in ipairs(STRIKE) do
    info(("STRIKE[%d] %s -> %s | qty=%d"):format(i, s.attacker, s.target, s.qty))
    for k = 1, s.qty do
        local delay = s.startDelay + (k - 1) * s.interval
        local tag = ("TOT_%d_%d_%s"):format(i, k, s.tag)
        if scheduleOne(s.attacker, s.target, s.wpn_dbid, delay, tag) then
            total_sched = total_sched + 1
        end
    end
end

ok(string.format("STRIKE 调度完成: %d 个触发器 (每枚 1 个事件)", total_sched))
